sources.ReceiptPanel.ets:
@Component
export struct ReceiptPanel {
  body: string = ''
  build() {
    Column() { Text(this.cleanBody()) }
  }
  cleanBody(): string {
    return this.body.replace('<p>', '').replace('</p>', '')
  }
}

